output.message:
{
  "steps": [
    {
      "step_id": "cb_step_1",
      "title": "Choose the scan for planning",
      "simple": "Select the CT volume you will use to create the skull segmentation.",
      "detailed": "This step chooses the image data that will serve as the basis for segmenting the skull. Bone appears bright on CT, so the selected scan determines how accurately the thresholding and all later 3D planning steps can identify the anatomy. Pick the volume with the clearest bony detail, usually a high-resolution CT."
    },
    {
      "step_id": "cb_step_2",
      "title": "Create a cranial segmentation",
      "simple": "Create a new segmentation named Cranial_Segmentation.",
      "detailed": "Segmentation stores a separate 3D representation of the skull while preserving the original image. Naming it clearly helps you keep track of the bone model used for symmetry analysis and implant planning."
    },
    {
      "step_id": "cb_step_3",
      "title": "Add and name the skull segment",
      "simple": "Click Add and rename the new segment to Cranial_Segment.",
      "detailed": "This creates a dedicated segment inside the segmentation where the thresholded bone will be stored. It ensures the bone model is kept separate from other structures and can be selected in later steps."
    },
    {
      "step_id": "cb_step_4",
      "title": "Open the threshold tool",
      "simple": "Click the Threshold button to open the thresholding tool.",
      "detailed": "Thresholding selects structures by their image intensity, which corresponds to tissue density. For CT bone, it highlights bright voxels and provides the starting point for isolating the skull before surgical planning."
    },
    {
      "step_id": "cb_step_5",
      "title": "Set the bone threshold range",
      "simple": "Drag the threshold range so the highlighted region covers the skull bone but not soft tissue or air.",
      "detailed": "The threshold range determines which tissue densities are included in the segmentation. Bone has high density, so choose a lower bound above soft tissue and an upper bound that still captures cortical bone. A range that is too narrow may lose thin bone, while one that is too wide can include unwanted structures."
    },
    {
      "step_id": "cb_step_6",
      "title": "Apply the threshold",
      "simple": "Click Apply to generate the initial skull segmentation.",
      "detailed": "Apply creates the actual bone segment from the threshold range. This 3D bone model is the starting point that will be cropped, separated, and analyzed in the following steps. Check that the main skull shape is present before moving on."
    },
    {
      "step_id": "cb_step_7",
      "title": "Select the skull segment",
      "simple": "Choose Cranial_Segment as the skull segmentation used for planning.",
      "detailed": "The planner needs to know which segmented anatomy represents the skull. Selecting the correct segment ensures that symmetry, cutting, and implant computations are performed on the bone model rather than on incidental structures."
    },
    {
      "step_id": "cb_step_8",
      "title": "Choose the entry points list",
      "simple": "In the Entry points section, select the point list that will hold the planned implant entry points.",
      "detailed": "Entry points mark where the zygomatic implants will enter the bone. They are collected in a point list that will be used together with the implant paths to define the planned trajectories. Use a list dedicated to this plan so the points stay organized."
    },
    {
      "step_id": "cb_step_9",
      "title": "Compute the symmetry plane",
      "simple": "Click the 'Compute symmetry plane' button.",
      "detailed": "This calculates the facial symmetry plane from the skull segment. The plane is the reference for cropping and for separating the upper and lower jaw, so a reliable plane keeps the following cuts symmetric and anatomically aligned."
    },
    {
      "step_id": "cb_step_10",
      "title": "Check the symmetry plane",
      "simple": "Decide if the computed symmetry plane needs manual adjustment.",
      "detailed": "If the scan is symmetric and the plane looks aligned with the facial midline, leave the checkbox unticked and continue. If the plane is tilted or offset, tick the checkbox so you can correct it in the next step. The symmetry plane is used as the geometric reference for later cuts."
    },
    {
      "step_id": "cb_step_11",
      "title": "Adjust the symmetry plane",
      "simple": "Position the plane along the facial midline in the view, then click Done.",
      "detailed": "Align the plane so it passes through midline structures and clearly symmetric landmarks. An accurate plane gives a stable reference for the cylindrical cut and jaw separation. Place only one plane, then confirm with Done."
    },
    {
      "step_id": "cb_step_12",
      "title": "Apply the symmetry plane adjustment",
      "simple": "Click 'Apply adjustment' to confirm the corrected plane.",
      "detailed": "This confirms the manual symmetry plane and stores it for use by the subsequent cutting and separation steps. After applying, the planner uses the adjusted orientation rather than the automatically computed one."
    },
    {
      "step_id": "cb_step_13",
      "title": "Set the crop radius",
      "simple": "Adjust the crop radius to define how much skull bone is kept around the surgical area.",
      "detailed": "The crop radius sets the size of the cylindrical region that will be retained around the maxillary and zygomatic area. Too small may exclude important anatomy, while too large may retain the mandible or the opposite side. Choose a radius that comfortably includes the zygomatic region and the planned implant paths."
    },
    {
      "step_id": "cb_step_14",
      "title": "Cut the skull to the planning region",
      "simple": "Click 'Cut skull (cylinder)' to trim the skull model to the selected region.",
      "detailed": "This applies a cylindrical cut around the planning area, keeping the relevant maxillary and zygomatic bone and removing most of the distant skull. It makes the remaining calculations faster and may also separate the maxilla from the mandible if the cut passes between them."
    },
    {
      "step_id": "cb_step_15",
      "title": "Check whether the mandible remains attached",
      "simple": "Decide whether the lower jaw is still attached to the upper jaw after the cut.",
      "detailed": "In zygomatic implant planning the maxilla should be separate from the mandible so the implant trajectories are planned without interference. If the cut did not fully separate them, tick the checkbox and proceed to the automatic separation step. If they are already separate, continue."
    },
    {
      "step_id": "cb_step_16",
      "title": "Separate the upper and lower jaw",
      "simple": "Click 'Separate maxilla / mandible' to divide the remaining bone.",
      "detailed": "This automatically splits the remaining skull into maxilla and mandible, isolating the upper jaw and zygomatic area for implant planning. If the separation boundary is imperfect, the next step lets you adjust the separating plane manually."
    },
    {
      "step_id": "cb_step_17",
      "title": "Check the separation plane",
      "simple": "Decide if the automatic separation between maxilla and mandible needs manual correction.",
      "detailed": "Fused or irregular bone can leave the maxilla and mandible not fully separated, or the cut can remove important bone. If the boundary looks wrong, tick the checkbox to adjust the segmentation plane. A clean separation is needed before identifying the zygomatic bones."
    },
    {
      "step_id": "cb_step_18",
      "title": "Refine the separation plane",
      "simple": "Position the separation plane along the desired maxilla–mandible boundary, then click Done.",
      "detailed": "Move and rotate the plane so it follows the junction where you want the maxilla and mandible to be divided. This corrects any areas that the automatic separation missed. Confirm the plane with Done so the separation can be applied."
    },
    {
      "step_id": "cb_step_19",
      "title": "Apply the separation",
      "simple": "Click 'Apply separation' to finalize the division.",
      "detailed": "This uses the adjusted plane to complete the maxilla–mandible split. The resulting isolated maxillary and zygomatic bone is then used for zygomatic identification and implant path planning."
    },
    {
      "step_id": "cb_step_20",
      "title": "Identify the zygomatic bones",
      "simple": "Click 'Identify zygomatic bones' to locate the cheekbone regions.",
      "detailed": "The planner uses the isolated maxilla to identify the zygomatic bone, which is the main anchor for zygomatic implants. Correct identification defines the bone volume available for implant support. If the region is not satisfactory, the next boundary-plane step lets you correct it."
    },
    {
      "step_id": "cb_step_21",
      "title": "Check the zygomatic boundaries",
      "simple": "Decide if the automatically identified zygomatic boundaries need manual adjustment.",
      "detailed": "The boundary planes define the limits of the zygomatic region used for generating implant paths. If the region seems too large, too small, or misplaced, tick the checkbox to adjust it. Otherwise continue to path generation."
    },
    {
      "step_id": "cb_step_22",
      "title": "Adjust a boundary plane",
      "simple": "Position one boundary plane where the zygomatic region should end, then click Done.",
      "detailed": "Boundary planes mark the edges of the bone region available for implant planning. Place one plane at a time according to the intended boundary, and click Done after each plane. This confines implant path generation to the correct anatomical area."
    },
    {
      "step_id": "cb_step_23",
      "title": "Apply the boundary planes",
      "simple": "Click 'Apply boundaries' to accept the adjusted boundary planes.",
      "detailed": "This confirms the manually placed boundaries and restricts the subsequent implant path planning to the corrected zygomatic region. Check that the highlighted region corresponds to the intended bone area before generating paths."
    },
    {
      "step_id": "cb_step_24",
      "title": "Generate implant paths",
      "simple": "Click 'Generate Implant paths' to create proposed trajectories for the zygomatic implants.",
      "detailed": "The planner computes possible implant trajectories from the entry points to suitable anchorage in the zygomatic bone. These paths show the planned direction, length, and bone support for each implant. Review them in the 3D view to decide whether manual refinement is needed."
    },
    {
      "step_id": "cb_step_25",
      "title": "Check the implant paths",
      "simple": "Decide if the generated implant paths need manual adjustment.",
      "detailed": "If the paths have poor angulation, insufficient bone support, or an undesirable length, tick the checkbox to refine them manually. If the plan looks appropriate, no further adjustment is needed and the planning is complete."
    },
    {
      "step_id": "cb_step_26",
      "title": "Adjust an implant path",
      "simple": "Place one implant path in the view according to the desired trajectory, then click Done.",
      "detailed": "A path represents the planned trajectory from the entry point to the implant position in the bone. Place one path at a time with the intended start and end, and click Done after each path. This lets you correct or replace individual paths before finalizing the plan."
    },
    {
      "step_id": "cb_step_27",
      "title": "Apply the path adjustments",
      "simple": "Click 'Apply paths' to save the adjusted implant trajectories.",
      "detailed": "This finalizes the manually corrected paths as the definitive implant plan. After this step, the planned zygomatic implant trajectories are ready for review and use in surgery."
    }
  ]
}
